static TRAIT_REPLY_COUNTER: AtomicU64 = AtomicU64::new(1);

type TraitReplyChannel = tokio::sync::oneshot::Sender<std::result::Result<String, String>>;

static TRAIT_REPLY_CHANNELS: std::sync::LazyLock<Mutex<HashMap<u64, TraitReplyChannel>>> =
    std::sync::LazyLock::new(|| Mutex::new(HashMap::new()));

#[rustler::nif(schedule = "DirtyCpu")]
pub fn convert(html: String, options: Option<String>) -> Result<ConversionResult, String> {
    html_to_markdown_rs::convert(
        &html,
        options
            .map(|s| serde_json::from_str::<html_to_markdown_rs::options::ConversionOptions>(&s).unwrap_or_default()),
    )
    .map(|val| val.into())
    .map_err(|e| e.to_string())
}

// Async visitor variant: pops visitor from options, builds bridge, spawns thread.
#[rustler::nif]
pub fn convert_with_visitor(
    env: rustler::Env<'_>,
    html: String,
    options: Option<String>,
    visitor: rustler::Term<'_>,
) -> Result<(), String> {
    let pid = env.pid();
    let mut visitor_owned_env = rustler::OwnedEnv::new();
    let visitor_saved = visitor_owned_env.save(visitor);
    let html = html.clone();

    std::thread::spawn(move || {
        let _ = visitor_owned_env.send_and_clear(&pid, |env| {
            let visitor_term = visitor_saved.load(env);
            let mut options_core: html_to_markdown_rs::options::ConversionOptions = options
                .map(|s| {
                    serde_json::from_str::<html_to_markdown_rs::options::ConversionOptions>(&s).unwrap_or_default()
                })
                .unwrap_or_default();
            let bridge = ElixirHtmlVisitorBridge::new(env, pid, visitor_term);
            options_core.visitor =
                Some(std::sync::Arc::new(std::sync::Mutex::new(bridge)) as html_to_markdown_rs::VisitorHandle);

            // Run conversion and return result term to send back to BEAM
            let conversion_result: Result<ConversionResult, String> =
                match html_to_markdown_rs::convert(&html, Some(options_core)) {
                    Ok(val) => {
                        let result: ConversionResult = val.into();
                        Ok(result)
                    }
                    Err(e) => Err(e.to_string()),
                };
            match conversion_result {
                Ok(result) => {
                    let ok_atom = rustler::types::atom::Atom::from_str(env, "ok").unwrap().to_term(env);
                    rustler::types::tuple::make_tuple(env, &[ok_atom, result.encode(env)])
                }
                Err(reason) => {
                    let err_atom = rustler::types::atom::Atom::from_str(env, "error").unwrap().to_term(env);
                    let reason_term = reason.encode(env);
                    rustler::types::tuple::make_tuple(env, &[err_atom, reason_term])
                }
            }
        });
    });
    Ok(())
}

fn nodecontext_to_elixir_map<'a>(env: rustler::Env<'a>, ctx: &html_to_markdown_rs::NodeContext) -> rustler::Term<'a> {
    let pairs: Vec<(rustler::Term<'a>, rustler::Term<'a>)> = vec![
        (
            rustler::types::atom::Atom::from_str(env, "node_type")
                .unwrap()
                .to_term(env),
            format!("{:?}", ctx.node_type).encode(env),
        ),
        (
            rustler::types::atom::Atom::from_str(env, "tag_name")
                .unwrap()
                .to_term(env),
            ctx.tag_name.encode(env),
        ),
        (
            rustler::types::atom::Atom::from_str(env, "depth").unwrap().to_term(env),
            (ctx.depth as i64).encode(env),
        ),
        (
            rustler::types::atom::Atom::from_str(env, "index_in_parent")
                .unwrap()
                .to_term(env),
            (ctx.index_in_parent as i64).encode(env),
        ),
        (
            rustler::types::atom::Atom::from_str(env, "parent_tag")
                .unwrap()
                .to_term(env),
            match ctx.parent_tag.as_deref() {
                Some(value) => value.encode(env),
                None => rustler::types::atom::Atom::from_str(env, "nil").unwrap().to_term(env),
            },
        ),
        (
            rustler::types::atom::Atom::from_str(env, "is_inline")
                .unwrap()
                .to_term(env),
            ctx.is_inline.encode(env),
        ),
    ];
    rustler::Term::map_from_pairs(env, &pairs)
        .unwrap_or_else(|_| rustler::types::atom::Atom::from_str(env, "nil").unwrap().to_term(env))
}
static VISITOR_REPLY_COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);
static VISITOR_CHANNELS: std::sync::LazyLock<
    std::sync::Mutex<std::collections::HashMap<u64, std::sync::mpsc::SyncSender<Option<String>>>>,
> = std::sync::LazyLock::new(|| std::sync::Mutex::new(std::collections::HashMap::new()));

// Bound on how long a visitor callback waits for the Elixir-side handler to reply before
// giving up and falling back to the method's default result. Mirrors the trait-bridge
// watchdog (`arm_trait_call_timeout` in `trait_support_nifs.rs.jinja`): if the calling
// process has already exited, `send_and_clear` is a silent no-op in the BEAM and no reply
// ever arrives, so an unbounded `rx.recv()` would block the OS thread forever.
const VISITOR_CALL_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(10);

// Spawn a watchdog that abandons `ref_id` if it is still pending after
// `VISITOR_CALL_TIMEOUT`. A no-op if the call already completed (`visitor_reply` removes
// the entry first). Dropping the sender makes the blocked `rx.recv()` in
// `visitor_send_and_wait` return `Err`, which `.ok().flatten()` already turns into `None`
// (the same "no reply" fallback used when the channel closes for any other reason).
fn arm_visitor_call_timeout(ref_id: u64) {
    std::thread::spawn(move || {
        std::thread::sleep(VISITOR_CALL_TIMEOUT);
        if let Ok(mut channels) = VISITOR_CHANNELS.lock()
            && channels.remove(&ref_id).is_some()
        {
            tracing::warn!(
                ref_id,
                timeout = ?VISITOR_CALL_TIMEOUT,
                "visitor callback timed out (host process may have exited without replying)"
            );
        }
    });
}
pub struct ElixirHtmlVisitorBridge {
    caller_pid: rustler::types::LocalPid,
    visitor_env: rustler::OwnedEnv,
    visitor_saved: rustler::env::SavedTerm,
}
impl std::fmt::Debug for ElixirHtmlVisitorBridge {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "ElixirHtmlVisitorBridge")
    }
}
impl ElixirHtmlVisitorBridge {
    pub fn new(env: rustler::Env<'_>, caller_pid: rustler::types::LocalPid, visitor_term: rustler::Term<'_>) -> Self {
        let owned = rustler::OwnedEnv::new();
        let saved = owned.save(visitor_term);
        Self {
            caller_pid,
            visitor_env: owned,
            visitor_saved: saved,
        }
    }

    pub fn new_from_saved(
        caller_pid: rustler::types::LocalPid,
        visitor_env: rustler::OwnedEnv,
        visitor_saved: rustler::env::SavedTerm,
    ) -> Self {
        Self {
            caller_pid,
            visitor_env,
            visitor_saved,
        }
    }
}
fn visitor_send_and_wait<F>(bridge: &ElixirHtmlVisitorBridge, callback_name: &str, build_args: F) -> Option<String>
where
    F: for<'a> FnOnce(rustler::Env<'a>) -> rustler::Term<'a>,
{
    let (tx, rx) = std::sync::mpsc::sync_channel::<Option<String>>(1);
    let ref_id = VISITOR_REPLY_COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    VISITOR_CHANNELS.lock().unwrap().insert(ref_id, tx);
    arm_visitor_call_timeout(ref_id);
    let pid = bridge.caller_pid;
    let cb_name = callback_name.to_string();
    let mut msg_env = rustler::OwnedEnv::new();
    let _ = msg_env.send_and_clear(&pid, |env| {
        let tag = rustler::types::atom::Atom::from_str(env, "visitor_callback")
            .unwrap()
            .to_term(env);
        let ref_term = ref_id.encode(env);
        let name_term = rustler::types::atom::Atom::from_str(env, &cb_name)
            .unwrap()
            .to_term(env);
        let args_term = build_args(env);
        rustler::types::tuple::make_tuple(env, &[tag, ref_term, name_term, args_term])
    });
    let result = rx.recv().ok().flatten();
    VISITOR_CHANNELS.lock().unwrap().remove(&ref_id);
    result
}
#[rustler::nif]
pub fn visitor_reply(ref_id: u64, result: Option<String>) {
    if let Some(tx) = VISITOR_CHANNELS.lock().unwrap().get(&ref_id) {
        let _ = tx.send(result);
    }
}
