    fn visit_text(&mut self, _ctx: &html_to_markdown_rs::NodeContext, _text: &str) -> html_to_markdown_rs::VisitResult {
        let _ctx_arg = NodeContext::from((*_ctx).clone());
        let _text_arg = _text.to_string();
        let result = visitor_send_and_wait(self, "handle_text", |env| {
            let mut args_map = rustler::Term::map_new(env);
            args_map = args_map
                .map_put("ctx".encode(env), _ctx_arg.encode(env))
                .expect("map_put");
            args_map = args_map
                .map_put("text".encode(env), _text_arg.encode(env))
                .expect("map_put");
            args_map
        });
        match result {
            None => html_to_markdown_rs::VisitResult::Continue,
            Some(s) => match s.as_str() {
                "continue" => html_to_markdown_rs::VisitResult::Continue,
                "skip" => html_to_markdown_rs::VisitResult::Skip,
                "preserve_html" => html_to_markdown_rs::VisitResult::PreserveHtml,
                _ => html_to_markdown_rs::VisitResult::Custom(s),
            },
        }
    }
