/// Validate that the header level is within valid range (1-6).
///
/// # Returns
///
/// `true` if level is 1-6, `false` otherwise.
///
/// # Examples
///
/// ```
/// let valid = HeaderMetadata {
///     level: 3,
///     text: "Title".to_string(),
///     id: None,
///     depth: 2,
///     html_offset: 100,
/// };
/// assert!(valid.is_valid());
///
/// let invalid = HeaderMetadata {
///     level: 7,  // Invalid
///     text: "Title".to_string(),
///     id: None,
///     depth: 2,
///     html_offset: 100,
/// };
/// assert!(!invalid.is_valid());
/// ```
#[rustler::nif]
pub fn headermetadata_is_valid(obj: HeaderMetadata) -> bool {
    html_to_markdown_rs::metadata::HeaderMetadata::from(obj).is_valid()
}

/// Return a reference to the attribute map.
///
/// If the context was built with `NodeContext::with_lazy_attributes`, the
/// map is materialized on the first call and cached for subsequent calls.
/// If this method is never called, no allocation occurs for attributes.
#[rustler::nif]
pub fn nodecontext_attributes(obj: NodeContext) -> HashMap<String, String> {
    html_to_markdown_rs::NodeContext::from(obj)
        .attributes()
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect()
}

/// Construct a `NodeContext` with an owned attribute map.
///
/// Use this when the caller already has materialized attributes.
#[rustler::nif]
pub fn nodecontext_with_owned_attributes(
    node_type: NodeType,
    tag_name: String,
    attributes: HashMap<String, String>,
    depth: usize,
    index_in_parent: usize,
    parent_tag: Option<String>,
    is_inline: bool,
) -> NodeContext {
    let node_type_core: html_to_markdown_rs::NodeType = node_type.into();
    html_to_markdown_rs::NodeContext::with_owned_attributes(
        node_type_core,
        tag_name.into(),
        attributes.into_iter().collect::<std::collections::BTreeMap<_, _>>(),
        depth,
        index_in_parent,
        parent_tag.map(std::borrow::Cow::Owned),
        is_inline,
    )
    .into()
}

/// Promote any borrowed fields into owned storage so the context can outlive `'a`.
#[rustler::nif]
pub fn nodecontext_into_owned(obj: NodeContext) -> NodeContext {
    html_to_markdown_rs::NodeContext::from(obj).into_owned().into()
}

#[rustler::nif]
pub fn preprocessingoptions_default() -> PreprocessingOptions {
    html_to_markdown_rs::options::PreprocessingOptions::default().into()
}

