impl From<html_to_markdown_rs::VisitResult> for VisitResult {
    fn from(val: html_to_markdown_rs::VisitResult) -> Self {
        match val {
            html_to_markdown_rs::VisitResult::Continue => Self {
                r#type: "continue".to_string(),
                ..Default::default()
            },
            html_to_markdown_rs::VisitResult::Custom(_0) => Self {
                r#type: "custom".to_string(),
                custom: Some(_0),
                ..Default::default()
            },
            html_to_markdown_rs::VisitResult::Skip => Self {
                r#type: "skip".to_string(),
                ..Default::default()
            },
            html_to_markdown_rs::VisitResult::PreserveHtml => Self {
                r#type: "preserve_html".to_string(),
                ..Default::default()
            },
            html_to_markdown_rs::VisitResult::Error(_0) => Self {
                r#type: "error".to_string(),
                error: Some(_0),
                ..Default::default()
            },
        }
    }
}

impl From<VisitResult> for html_to_markdown_rs::VisitResult {
    fn from(val: VisitResult) -> Self {
        match val.r#type.as_str() {
            "continue" => html_to_markdown_rs::VisitResult::Continue,
            "custom" => html_to_markdown_rs::VisitResult::Custom(val.custom.unwrap_or_default()),
            "skip" => html_to_markdown_rs::VisitResult::Skip,
            "preserve_html" => html_to_markdown_rs::VisitResult::PreserveHtml,
            "error" => html_to_markdown_rs::VisitResult::Error(val.error.unwrap_or_default()),
            _ => Default::default(),
        }
    }
}

